style.css:
::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

::-webkit-scrollbar-track{
  background-color: white;
  border: black 2px solid;
}

::-webkit-scrollbar-thumb{
  background-color: linear-gradient(to top, red, orange, yellow, green, blue, purple, pink);
  border: black 2px solid;
}

::-webkit-scrollbar-thumb:hover{
  background:
    url(https://i.pinimg.com/originals/87/76/ee/8776eefe1b715f5a83280cfba0a8f4b8.gif);
  background-size: 1000px;
}
